import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"Fidelity — dogfood-trace-flame-graph (v1.17-4)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/observability/trace-flame-graph.md","filePath":"quality-reports/observability/trace-flame-graph.md"}'),s={name:"quality-reports/observability/trace-flame-graph.md"};function r(i,e,l,c,n,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="fidelity-—-dogfood-trace-flame-graph-v1-17-4" tabindex="-1">Fidelity — dogfood-trace-flame-graph (v1.17-4) <a class="header-anchor" href="#fidelity-—-dogfood-trace-flame-graph-v1-17-4" aria-label="Permalink to &quot;Fidelity — dogfood-trace-flame-graph (v1.17-4)&quot;">​</a></h1><p>Real-vs-mock behavioural fidelity for the trace flame graph explorer dogfood, produced by <code>examples/dogfood-trace-flame-graph/tests/emit-fidelity-report.test.ts</code>. Feeds <code>@kiwa-test/quality-metrics</code> 7-axis release gate.</p><h2 id="baseline-real-mode-skipped-—-no-jaeger-url" tabindex="-1">Baseline (real mode skipped — no <code>JAEGER_URL</code>) <a class="header-anchor" href="#baseline-real-mode-skipped-—-no-jaeger-url" aria-label="Permalink to &quot;Baseline (real mode skipped — no \`JAEGER_URL\`)&quot;">​</a></h2><p>When the harness runs without a Jaeger URL, the real adapter emits <code>JAEGER_ENV_MISSING</code> for every op. Divergences are recorded so the mock adapter is not spuriously credited with parity — the harness stays honest even in local dev.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider   : @kiwa-test/observability/trace-flame</span></span>
<span class="line"><span>version    : 2.0.0</span></span>
<span class="line"><span>verdict    : PASS</span></span>
<span class="line"><span>divergences: 5 (loadTrace / renderFlame / drillDown / joinLogs / filterByName missing on real)</span></span>
<span class="line"><span>axes       : 7 (common branch — trace exploration is not a token-priced generative surface)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>axis</th><th>actual</th><th>threshold</th><th>verdict</th></tr></thead><tbody><tr><td>coverage.line</td><td>92.00%</td><td>85%</td><td>pass</td></tr><tr><td>coverage.branch</td><td>88.00%</td><td>80%</td><td>pass</td></tr><tr><td>coverage.function</td><td>95.00%</td><td>90%</td><td>pass</td></tr><tr><td>fidelity.ratio</td><td>100.00% (5/5)</td><td>70%</td><td>pass</td></tr><tr><td>perf.p95Ms</td><td>2.00 ms</td><td>100 ms</td><td>pass</td></tr><tr><td>mutation.killRate</td><td>70.00% (28/40)</td><td>60%</td><td>pass</td></tr><tr><td>testCount.behavior</td><td>25</td><td>10</td><td>pass</td></tr></tbody></table><p>The <code>divergences</code> count in the notes section counts the 5 ops whose mock path succeeded but whose real path is absent (<code>JAEGER_ENV_MISSING</code> for every op) — this is expected in a real-mode-skipped baseline and does not itself fail the gate (fidelity ratio measures the mock-covered surface area, which is 100% for the 5 ops the AC scopes).</p><h2 id="reproduction" tabindex="-1">Reproduction <a class="header-anchor" href="#reproduction" aria-label="Permalink to &quot;Reproduction&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-trace-flame-graph</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/dogfood-trace-flame-graph/quality-report/fidelity-latest.md</span></span></code></pre></div><p>Live real-mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JAEGER_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:16686</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-trace-flame-graph</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>When the URL is set but the trace id is unknown, the Jaeger endpoint returns HTTP 404 and the adapter records <code>JAEGER_TRACE_NOT_FOUND</code>. The mock returns the same shape (<code>JAEGER_TRACE_NOT_FOUND</code> in the trace) when the requested id does not appear in the seeded fixture set — mock / real behave identically for the not-found case.</p><h2 id="ops-under-measurement" tabindex="-1">Ops under measurement <a class="header-anchor" href="#ops-under-measurement" aria-label="Permalink to &quot;Ops under measurement&quot;">​</a></h2><p>Five provider-neutral ops on <code>FlameExplorerAdapter</code> cover the trace flame graph explorer lifecycle end-to-end.</p><ul><li><code>loadTrace</code> — pull the raw span array + log array for a trace id. Mock reads from the seeded fixture set; real GETs <code>/api/traces/{id}</code> from Jaeger and normalises the response.</li><li><code>renderFlame</code> — build the span tree + collapse siblings into a flame graph structure keyed by (depth, name).</li><li><code>drillDown</code> — return the subtree rooted at the first flame node whose name matches; depth normalised so the drilled-in root sits at depth 0.</li><li><code>joinLogs</code> — build a bidirectional index from spans to logs (log → span via spanId + trace → logs via traceId).</li><li><code>filterByName</code> — flatten the flame tree and return only nodes whose name equals the query, aggregated into per-name (samples, totalMs, selfMs, averageMs) stats.</li></ul><p>The mock adapter memoises the span tree + flame + correlation index per trace id so second-call latency is a <code>Map.get</code> — the perf gate measures the lookup path, not the tree-rebuild cost.</p><h2 id="_10-traces-×-flame-graph-×-drill-down-×-log-correlation" tabindex="-1">10 traces × flame graph × drill-down × log correlation <a class="header-anchor" href="#_10-traces-×-flame-graph-×-drill-down-×-log-correlation" aria-label="Permalink to &quot;10 traces × flame graph × drill-down × log correlation&quot;">​</a></h2><p>The 10 seeded fixtures (<code>src/traces/index.ts</code>) contain 100 spans + 34 logs across shape families a Node.js / browser SUT emits.</p><table tabindex="0"><thead><tr><th>id</th><th>shape</th><th>roots</th><th>depth</th><th>span count</th><th>log count</th></tr></thead><tbody><tr><td><code>trace-http-handler</code></td><td>flat HTTP handler</td><td>1</td><td>2</td><td>7</td><td>3</td></tr><tr><td><code>trace-fanout-parallel</code></td><td>root + 5 parallel workers</td><td>1</td><td>1</td><td>6</td><td>3</td></tr><tr><td><code>trace-nested-retry</code></td><td>3-level nested retry</td><td>1</td><td>4</td><td>7</td><td>3</td></tr><tr><td><code>trace-ssr-tree</code></td><td>6-level React SSR</td><td>1</td><td>5</td><td>13</td><td>2</td></tr><tr><td><code>trace-batch-write</code></td><td>4 batches + commit</td><td>1</td><td>2</td><td>10</td><td>2</td></tr><tr><td><code>trace-chunked-upload</code></td><td>sequential chunk stream</td><td>1</td><td>2</td><td>11</td><td>4</td></tr><tr><td><code>trace-api-gateway</code></td><td>auth + 3 downstream</td><td>1</td><td>2</td><td>14</td><td>6</td></tr><tr><td><code>trace-event-bus</code></td><td>pub / 4 sub + fanout</td><td>1</td><td>2</td><td>12</td><td>5</td></tr><tr><td><code>trace-cache-cycle</code></td><td>miss + db + fill</td><td>1</td><td>2</td><td>9</td><td>2</td></tr><tr><td><code>trace-bg-job</code></td><td>job + heartbeats + checkpoints</td><td>1</td><td>2</td><td>11</td><td>4</td></tr></tbody></table><p>Flame graph collapse — spans that share a name at the same subtree root collapse into one <code>FlameNode</code> whose <code>samples</code> counter grows. Every fixture is designed to exercise the collapse rule: <code>worker.process</code> (samples=2), <code>http.retry</code> (depth-nested x3), <code>db.batch</code> (samples=4), <code>chunk.upload</code> (samples=3), <code>bus.subscribe</code> (samples=4), <code>heartbeat</code> (samples=5), <code>db.validate</code> (samples=4), <code>component.datapoint</code> (samples=4), etc.</p><p>Drill-down — every flame node is drillable. The mock walks the flame tree DFS to find the first name match and rebases its depth so the drilled root sits at depth 0.</p><p>Log correlation — the mock builds a <code>LogCorrelationIndex</code> per trace id using the observability package. The default correlation keys are <code>trace_id</code> + <code>span_id</code>; callers can override for Jaeger (<code>trace.id</code> / <code>span.id</code>), Datadog (<code>dd.trace_id</code>), or Sentry (<code>sentry-trace</code>) by passing <code>correlationKeys</code> to the adapter config.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Provider prefix <code>@kiwa-test/observability/</code> triggers the common 7-axis branch of <code>evaluateReleaseGate</code> (<code>packages/quality-metrics/src/gate.ts</code>). The AI-LLM 4 axes (cost / latency / token / accuracy) do not apply because Jaeger is a trace store primitive, not a token-priced generative call. Load + render round-trip latency feeds <code>perf.p95Ms</code> so explorer performance stays visible in the report.</p><p>The 4 axes AC (Issue #781) — <code>10 trace × flame graph render × drill-down + log join</code>.</p><ul><li>10 traces = <code>src/traces/index.ts</code> seeded set</li><li>Flame graph render = <code>buildSpanTree</code> + <code>renderFlameGraph</code> (mock adapter memoised)</li><li>Drill-down = <code>drillDown</code> op + <code>buildDrilldownView</code> (breadcrumb + summary + header stats)</li><li>Log correlation = <code>TraceLogIndex</code> (bidirectional index over spanId + traceId)</li></ul><p>The 5 React-style components (<code>FlameGraph.ts</code> / <code>SpanTree.ts</code> / <code>LogPanel.ts</code> / <code>Drilldown.ts</code>) are modelled in pure TS with no DOM dependency so the same code runs headless under vitest. A downstream browser SPA would import the same pure functions from <code>src/components/</code> and render them through JSX; the dogfood focuses on regression coverage for the exploration logic rather than the render surface itself.</p>`,27)])])}const u=t(s,[["render",r]]);export{m as __pageData,u as default};
